#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int mn(int a, int b)  {
    return a < b ? a : b;
}
int mx(int a, int b)  {
    return a > b ? a : b;
}
int read(void)  {
    int x = 0;
    if (scanf("%d", &x) != 1) return 0;
    return x;
}
int readstr(int* a)  {
    char s[20001];
    if (scanf("%20000s", s) != 1) return 0;
    if (strcmp(s, "-") == 0) return 0;
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) a[i] = (unsigned char)s[i];
    return n;
}
void emit(int x)  {
    printf("%d ", x);
}
void emitstr(int* a, int n)  {
    if (n == 0) putchar('-');
    for (int i = 0; i < n; i++) putchar(a[i]);
    putchar(' ');
}
int main(void)  {
    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, k = 0, n = 0;
    // 输入已按非降序排列；n 可以为 0，不能默认访问首元素。
    n = read();
    for (i = 0; i < n; i += 1)  {
        a[i] = read();
    }
    k = 0;
    for (i = 0; i < n; i += 1)  {
        // 有序数组的每组相同值只保留第一项；先判断 i=0 避免访问负下标。
        if ((i == 0) || (a[i] != a[(i - 1)]))  {
            b[k] = a[i];
            k = (k + 1);
        }
    }
    // 先输出保留数量，再输出 b 的前 k 个值。
    emit(k);
    for (i = 0; i < k; i += 1)  {
        emit(b[i]);
    }
    return 0;
}

